// Shortest Routes I | https://cses.fi/problemset/task/1671/
// Time: O((n + m) log(n + m)); extra space: O(n + m).
#include <iostream>
#include <vector>
#include <queue>
#include <functional>
#include <utility>
#include <limits>



void solve() {
    int n, m;
    std::cin >> n >> m;
    std::vector<std::vector<std::pair<int, long long>>> graph(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        long long cost;
        std::cin >> a >> b >> cost;
        graph[a - 1].emplace_back(b - 1, cost);
    }
    constexpr long long infinity = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> distance(n, infinity);
    using State = std::pair<long long, int>;
    std::priority_queue<State, std::vector<State>, std::greater<State>> queue;
    distance[0] = 0;
    queue.emplace(0, 0);
    while (!queue.empty()) {
        auto [cost, u] = queue.top(); queue.pop();
        if (cost != distance[u]) continue;
        for (auto [v, weight] : graph[u]) {
            if (cost + weight < distance[v]) {
                distance[v] = cost + weight;
                queue.emplace(distance[v], v);
            }
        }
    }
    for (int i = 0; i < n; ++i) std::cout << distance[i] << (i + 1 == n ? '\n' : ' ');
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    solve();
}

// Frog 1 | https://atcoder.jp/contests/dp/tasks/dp_a
// Time: O(n); extra space: O(n).
#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>
#include <limits>



void solve() {
    int n; std::cin >> n;
    std::vector<long long> height(n), best(n, std::numeric_limits<long long>::max() / 4);
    for (auto& value : height) std::cin >> value;
    best[0] = 0;
    for (int i = 1; i < n; ++i) {
        best[i] = best[i - 1] + std::abs(height[i] - height[i - 1]);
        if (i >= 2) best[i] = std::min(best[i], best[i - 2] + std::abs(height[i] - height[i - 2]));
    }
    std::cout << best.back() << '\n';
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    solve();
}

// Dynamic Range Sum Queries | https://cses.fi/problemset/task/1648/
// Time: O((n + q) log n); extra space: O(n).
#include <iostream>
#include <vector>



void solve() {
    int n, q;
    std::cin >> n >> q;
    std::vector<long long> values(n + 1), tree(n + 1);
    auto add = [&](int index, long long delta) {
        for (; index <= n; index += index & -index) tree[index] += delta;
    };
    auto prefix = [&](int index) {
        long long answer = 0;
        for (; index > 0; index -= index & -index) answer += tree[index];
        return answer;
    };
    for (int i = 1; i <= n; ++i) { std::cin >> values[i]; add(i, values[i]); }
    while (q--) {
        int type, a; long long b;
        std::cin >> type >> a >> b;
        if (type == 1) { add(a, b - values[a]); values[a] = b; }
        else std::cout << prefix(static_cast<int>(b)) - prefix(a - 1) << '\n';
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    solve();
}

// Book Shop | https://cses.fi/problemset/task/1158/
// Time: O(n * x); extra space: O(n + x).
#include <iostream>
#include <vector>
#include <algorithm>



void solve() {
    int n, budget;
    std::cin >> n >> budget;
    std::vector<int> price(n), pages(n), best(budget + 1);
    for (auto& value : price) std::cin >> value;
    for (auto& value : pages) std::cin >> value;
    for (int book = 0; book < n; ++book) {
        for (int money = budget; money >= price[book]; --money) {
            best[money] = std::max(best[money], best[money - price[book]] + pages[book]);
        }
    }
    std::cout << best[budget] << '\n';
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    solve();
}

// Factory Machines | https://cses.fi/problemset/task/1620/
// Time: O(n log(min(k) * t)); extra space: O(n).
#include <iostream>
#include <vector>
#include <algorithm>



void solve() {
    int n;
    long long target;
    std::cin >> n >> target;
    std::vector<long long> times(n);
    for (auto& time : times) std::cin >> time;
    long long low = 0;
    long long high = *std::min_element(times.begin(), times.end()) * target;
    auto enough = [&](long long duration) {
        long long made = 0;
        for (long long time : times) {
            long long produced = duration / time;
            if (produced >= target - made) return true;
            made += produced;
        }
        return false;
    };
    while (low < high) {
        long long middle = low + (high - low) / 2;
        if (enough(middle)) high = middle;
        else low = middle + 1;
    }
    std::cout << low << '\n';
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    solve();
}

// Same Differences | https://codeforces.com/problemset/problem/1520/D
// Time: O(n log n) per case; extra space: O(n).
#include <iostream>
#include <map>



void solve() {
    int tests; std::cin >> tests;
    while (tests-- > 0) {
        int n; std::cin >> n; std::map<long long,long long> frequency; long long answer=0;
        for (int i=0;i<n;++i) { long long value; std::cin >> value; answer+=frequency[value-i]++; }
        std::cout << answer << '\n';
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    solve();
}
